1	package indexroom
2	
3	import (
4		"math"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// This file is the domain-level regression guard for the registration revision
11	// ceiling. Revisions are carried by int and a real content change increments
12	// them; at the architecture's maximum (math.MaxInt — 2147483647 on a 32-bit
13	// build, 9223372036854775807 on a 64-bit build) another increment would
14	// overflow to a negative revision that no legal expectedRevision could ever
15	// match again. A content-changing replacement at the cap is therefore refused
16	// as invalid and changes nothing, while a submission with identical normalized
17	// content (including a pure reorder or whitespace-only differences) and an
18	// already-empty list resubmitted as [] still succeeds without bumping; a
19	// replacement at max-1 still increments to max.
20	//
21	// The state is placed directly at the cap: reaching it through billions of
22	// Apply calls would be impractically slow, and the ceiling semantics are
23	// independent of how the state got there.
24	
25	// seedAtRevision builds a service holding insts at exactly revision rev. The
26	// instances start unknown with sequence 0 and no reason; health records are
27	// added afterwards with markHealth at the service's revision.
28	func seedAtRevision(t *testing.T, r *Registry, service string, rev int, insts []Instance) {
29		t.Helper()
30		st := &serviceState{revision: rev, instances: make(map[string]*instanceState, len(insts))}
31		for _, inst := range insts {
32			st.instances[inst.ID] = newInstanceState(inst.Address)
33		}
34		r.services[service] = st
35	}
36	
37	// assertInvalidAtLimit checks the refusal shared by every change shape:
38	// ok:false, error invalid, the reason names the registration-revision limit
39	// and its value, revision stays the cap, changed is absent, and neither the
40	// expectedRevision/actualRevision comparison pair nor any target fields appear.
41	func assertInvalidAtLimit(t *testing.T, out Outcome, rev int) {
42		t.Helper()
43		if out.OK || out.Kind != OutcomeInvalid {
44			t.Fatalf("want invalid at the revision limit, got %+v", out)
45		}
46		if out.Changed || out.Expected != 0 || out.Actual != 0 || out.RevisionMismatch {
47			t.Fatalf("limit rejection must omit changed and the revision pair: %+v", out)
48		}
49		if out.Revision != rev {
50			t.Fatalf("revision must stay at the limit %d, got %d", rev, out.Revision)
51		}
52		if !strings.Contains(out.Reason, "registration revision has reached its limit") {
53			t.Fatalf("reason should state the registration revision limit, got %q", out.Reason)
54		}
55		if !strings.Contains(out.Reason, strconv.Itoa(rev)) {
56			t.Fatalf("reason should name the limit %d, got %q", rev, out.Reason)
57		}
58	}
59	
60	// TestRegistryRevisionLimitChangeShapesRefused walks the four change shapes the
61	// task names — adding, removing, changing an address and clearing a non-empty
62	// list — plus readding a removed instance, and verifies none takes effect.
63	func TestRegistryRevisionLimitChangeShapesRefused(t *testing.T) {
64		const limit = math.MaxInt
65	
66		r := NewRegistry()
67		seedAtRevision(t, r, "svc", limit, []Instance{
68			{ID: "i1", Address: "h1:1"},
69			{ID: "i2", Address: "h2:2"},
70		})
71		markHealth(t, r, "svc", "i1", int64(limit), 11, true, "")
72		markHealth(t, r, "svc", "i2", int64(limit), 22, true, "")
73	
74		// Establish a session binding and a rotation cursor before the refusals.
75		assertPick(t, selectSession(t, r, "svc", int64(limit), "user-42"), "i1", "h1:1", 11)
76		assertPick(t, selected(t, r, "svc", int64(limit)), "i2", "h2:2", 22)
77	
78		cases := []struct {
79			name string
80			list []Instance
81		}{
82			{"add an instance", []Instance{
83				{ID: "i1", Address: "h1:1"}, {ID: "i2", Address: "h2:2"}, {ID: "i3", Address: "h3:3"},
84			}},
85			{"remove an instance", []Instance{{ID: "i1", Address: "h1:1"}}},
86			{"change an address", []Instance{
87				{ID: "i1", Address: "h1:1"}, {ID: "i2", Address: "h9:9"},
88			}},
89			{"clear a non-empty list", nil},
90			{"remove then readd with a new address", []Instance{
91				{ID: "i1", Address: "h1:1"}, {ID: "i2", Address: "h4:4"},
92			}},
93		}
94		for _, tc := range cases {
95			t.Run(tc.name, func(t *testing.T) {
96				reg, err := r.ValidateRegistration("svc", int64(limit), tc.list)
97				if err != nil {
98					t.Fatalf("content at the cap must validate: %v", err)
99				}
100				assertInvalidAtLimit(t, r.Apply(reg), limit)
101	
102				// No change took effect: revision, list, health, reason, cursor and
103				// binding are the ones established beforehand.
104				views := r.Snapshot()
105				if len(views) != 1 || views[0].Revision != limit {
106					t.Fatalf("state changed after refused %s: %+v", tc.name, views)
107				}
108				if len(views[0].Instances) != 2 {
109					t.Fatalf("list changed after refused %s: %+v", tc.name, views[0].Instances)
110				}
111				if inst := instanceHealth(t, r, "svc", "i1"); inst.Address != "h1:1" ||
112					inst.Health != HealthHealthy || inst.Sequence != 11 || inst.Reason != "" {
113					t.Fatalf("i1 changed after refused %s: %+v", tc.name, inst)
114				}
115				if inst := instanceHealth(t, r, "svc", "i2"); inst.Address != "h2:2" ||
116					inst.Health != HealthHealthy || inst.Sequence != 22 || inst.Reason != "" {
117					t.Fatalf("i2 changed after refused %s: %+v", tc.name, inst)
118				}
119				// The rejected list rebuilt no map, so the rotation and the bound
120				// session consult the same instances with the same records.
121				assertPick(t, selectSession(t, r, "svc", int64(limit), "user-42"), "i1", "h1:1", 11)
122			})
123		}
124	
125		// Cursor and bindings are untouched: an ordinary select at the cap continues
126		// just after i2 (the last actually rotated id) and wraps to i1 — not i2
127		// again, which a rebuilt/reset state would have forced.
128		assertPick(t, selected(t, r, "svc", int64(limit)), "i1", "h1:1", 11)
129	}
130	
131	// TestRegistryRevisionLimitIdenticalContentSucceeds locks the other half: at
132	// the cap a matching submission whose normalized content is unchanged is a
133	// normal success with no changed field and an unchanged revision. This covers
134	// a plain duplicate, a pure reorder, field trimming, and an already-empty list
135	// resubmitted as an empty array.
136	func TestRegistryRevisionLimitIdenticalContentSucceeds(t *testing.T) {
137		const limit = math.MaxInt
138	
139		r := NewRegistry()
140		seedAtRevision(t, r, "svc", limit, []Instance{
141			{ID: "i1", Address: "h1:1"},
142			{ID: "i2", Address: "h2:2"},
143		})
144		markHealth(t, r, "svc", "i1", int64(limit), 11, true, "")
145	
146		identical := [][]Instance{
147			// Plain duplicate.
148			{{ID: "i1", Address: "h1:1"}, {ID: "i2", Address: "h2:2"}},
149			// Pure reorder: content unchanged by the existing rule.
150			{{ID: "i2", Address: "h2:2"}, {ID: "i1", Address: "h1:1"}},
151			// Whitespace padding around the service name, ids and addresses is
152			// trimmed during validation, so the normalized content is identical.
153			{{ID: " i1 ", Address: "  h1:1  "}, {ID: "\ti2\t", Address: " h2:2 "}},
154		}
155		for i, list := range identical {
156			reg, err := r.ValidateRegistration("  svc  ", int64(limit), list)
157			if err != nil {
