237		// reuse does not rotate.
238		if r := got.Results[12]; !r.OK || r.InstanceID != "i1" {
239			t.Fatalf("result 12 binding must survive the failed release: %+v", r)
240		}
241		// 13: a plain select continues just after the cursor left at i1 and gets i2.
242		if r := got.Results[13]; !r.OK || r.InstanceID != "i2" {
243			t.Fatalf("result 13 plain rotation must continue at i2: %+v", r)
244		}
245	
246		// Final state reflects only accepted items: revision 2, all three
247		// instances present, i1/i2 still healthy at sequence 1 (the failed seq 9
248		// report never applied), i3 unknown at sequence 0.
249		if len(got.Services) != 1 {
250			t.Fatalf("services: %+v", got.Services)
251		}
252		svc := got.Services[0]
253		if svc.Service != "svc" || svc.Revision != 2 || len(svc.Instances) != 3 {
254			t.Fatalf("final service: %+v", svc)
255		}
256		want := []struct {
257			id, health string
258			sequence   int64
259		}{
260			{"i1", "healthy", 1},
261			{"i2", "healthy", 1},
262			{"i3", "unknown", 0},
263		}
264		for i, w := range want {
265			inst := svc.Instances[i]
266			if inst.ID != w.id || inst.Health != w.health || inst.Sequence != w.sequence {
267				t.Fatalf("instance %d: got %+v, want id %s health %s seq %d", i, inst, w.id, w.health, w.sequence)
268			}
269		}
270	}
